index 7a3ed2b..d79844d 100644
--- a/app/billing/upgrade.ts
+++ b/app/billing/upgrade.ts
@@ -5,9 +5,17 @@ import { planById } from "./plans";
 export async function upgradePlan(accountId: string, toPlanId: string): Promise<void> {
   const subscription = await db.subscriptions.findByAccount(accountId);
   const toPlan = await planById(toPlanId);
+  const anchor = new Date();
   await db.subscriptions.update(subscription.id, {
     planId: toPlan.id,
     priceCents: toPlan.priceCents,
+    billingCycleAnchor: anchor,
   });
   events.emit("subscription.changed", { accountId });
+  events.emit("plan.upgraded", {
+    accountId,
+    fromPlan: subscription.planId,
+    toPlan: toPlan.id,
+    anchor: anchor.toISOString(),
+  });
 }
