@@ -1,6 +1,6 @@
 const ZERO_DECIMAL = new Set(["JPY", "KRW"]);

-export function formatCents(amount: number, currency = "USD"): string {
+export function formatMinorUnits(amount: number, currency = "USD"): string {
   const divisor = ZERO_DECIMAL.has(currency) ? 1 : 100;
   return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount / divisor);
 }
