index 0000000..a020570
--- /dev/null
+++ b/db/migrations/20261118093000_add_billing_cycle_anchor.sql
@@ -0,0 +1,6 @@
+-- Anchor each subscription's billing cycle so mid-cycle upgrades restart the period.
+ALTER TABLE subscriptions ADD COLUMN billing_cycle_anchor timestamptz;
+
+UPDATE subscriptions SET billing_cycle_anchor = created_at WHERE billing_cycle_anchor IS NULL;
+
+ALTER TABLE subscriptions ALTER COLUMN billing_cycle_anchor SET NOT NULL;
